import p1 from "../../../images/property/prop-1.jpg";
import p1sm from "../../../images/property/prop-1-sm.jpg";
import p2 from "../../../images/property/prop-2.jpg";
import p2sm from "../../../images/property/prop-2-sm.jpg";
import p3 from "../../../images/property/prop-3.jpg";
import p3sm from "../../../images/property/prop-3-sm.jpg";
import p4 from "../../../images/property/prop-4.jpg";
import p4sm from "../../../images/property/prop-4-sm.jpg";
import p5 from "../../../images/property/prop-5.jpg";
import p5sm from "../../../images/property/prop-5-sm.jpg";

import p6 from "../../../images/property/prop-6.jpg";
import p6sm from "../../../images/property/prop-6-sm.jpg";
import p7 from "../../../images/property/prop-7.jpg";
import p7sm from "../../../images/property/prop-7-sm.jpg";
import p8 from "../../../images/property/prop-8.jpg";
import p8sm from "../../../images/property/prop-8-sm.jpg";
import p9 from "../../../images/property/prop-9.jpg";
import p9sm from "../../../images/property/prop-9-sm.jpg";
import p10 from "../../../images/property/prop-10.jpg";
import p10sm from "../../../images/property/prop-10-sm.jpg";
import p11 from "../../../images/property/prop-11.jpg";
import p11sm from "../../../images/property/prop-11-sm.jpg";
import p12 from "../../../images/property/prop-12.jpg";
import p12sm from "../../../images/property/prop-12-sm.jpg";

const srcSet = (small: string, large: string) => `${small} 600w, ${large} 900w`;

/**
 * Image key to resolved asset.
 *
 * This is the only place property photographs are imported. Records name a
 * key; presentation resolves it here. When real listings arrive from a CMS
 * their images will be remote URLs and this map falls away — the records
 * themselves will not need to change shape.
 */
const IMAGES: Record<string, ResolvedImage> = {
  "prop-1": { src: p1, srcSet: srcSet(p1sm, p1) },
  "prop-2": { src: p2, srcSet: srcSet(p2sm, p2) },
  "prop-3": { src: p3, srcSet: srcSet(p3sm, p3) },
  "prop-4": { src: p4, srcSet: srcSet(p4sm, p4) },
  "prop-5": { src: p5, srcSet: srcSet(p5sm, p5) },
  "prop-6": { src: p6, srcSet: srcSet(p6sm, p6) },
  "prop-7": { src: p7, srcSet: srcSet(p7sm, p7) },
  "prop-8": { src: p8, srcSet: srcSet(p8sm, p8) },
  "prop-9": { src: p9, srcSet: srcSet(p9sm, p9) },
  "prop-10": { src: p10, srcSet: srcSet(p10sm, p10) },
  "prop-11": { src: p11, srcSet: srcSet(p11sm, p11) },
  "prop-12": { src: p12, srcSet: srcSet(p12sm, p12) },
};

/** Resolves one record's image key into the shape the card and hero expect. */
export function resolveProperty(record: PropertyRecord): Property {
  const image = IMAGES[record.imageKey];

  if (image) {
    return { ...record, image: image.src, imageSrcSet: image.srcSet };
  }

  /* No key, or a key nothing is registered under. Before assuming the property
     has no photograph, ask the property.

     A bundled listing names its photograph by key, because the file is in the
     repository and webpack has to see the import. A property created in the
     CMS carries its own `images`, already uploaded and already URLs — there is
     nothing in this map for it and there never will be.

     Without this fallback such a property rendered a photograph on its card
     (the CMS applies the same rule itself) and a blank space in its hero, its
     gallery strip and its search result. One rule here rather than four
     `withOwnImage` calls dotted around, because the day somebody adds a fifth
     surface it should not be their job to remember. */
  const own = featuredImage(record);

  if (own?.src) {
    return { ...record, image: own.src, imageSrcSet: own.srcSet };
  }

  if (record.imageKey && process.env.NODE_ENV !== "production") {
    /* Narrowed to records that NAME a key. A CMS property has no key by
       design, so warning about it would have trained everyone to ignore this
       — which is how the one real broken key gets missed. */
    console.warn(
      `[property] no image registered for key "${record.imageKey}" (${record.slug})`
    );
  }

  return { ...record, image: "", imageSrcSet: undefined };
}

export function resolveProperties(records: PropertyRecord[]): Property[] {
  return records.map(resolveProperty);
}

export default IMAGES;
